ALTER TABLE assessments MODIFY COLUMN kind ENUM('project','assignment','worksheet','case_study','activity') NOT NULL, ADD COLUMN allow_late BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE submissions ADD COLUMN version INT NOT NULL DEFAULT 1, ADD COLUMN returned_until DATETIME(3) NULL, ADD COLUMN file_id CHAR(36) NULL;
CREATE TABLE submission_files (id CHAR(36) PRIMARY KEY,assessment_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,name VARCHAR(180) NOT NULL,kind VARCHAR(10) NOT NULL,file_key VARCHAR(100) NOT NULL,file_size INT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(assessment_id) REFERENCES assessments(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE submission_events (id CHAR(36) PRIMARY KEY,submission_id CHAR(36) NOT NULL,actor_id CHAR(36) NOT NULL,event VARCHAR(20) NOT NULL,snapshot JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(submission_id) REFERENCES submissions(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
